"""Human pages in es and zh, generated from the English source and one phrase table per language
(00-docs/humans/<lang>/strings.json, English → translation). Only changed English text needs translating.

python3 .github/pages/i18n.py   writes the translated READMEs and syncs the tables: new English text is added
with an empty translation (fill it in, rerun), text no longer in the source is dropped. Empty → English shown."""
import json, pathlib, posixpath, re

LANGS = {"es": "es", "zh": "zh-Hans"}  # dir → html lang code
MD = {"README.md": "00-docs/humans/{lang}/README.md"}  # English source → generated, committed so GitHub shows them
LANDING = "00-docs/humans/landing.html"  # built into /<lang>/ by build.py, not committed
SITE = "https://opentokenmini.org/"
HEADER = "<!-- Generated by .github/pages/i18n.py from {src}: edit the English source and strings.json, not this file -->\n\n"
ROOT = pathlib.Path(__file__).parents[2]

def table_path(lang):
    return ROOT / "00-docs/humans" / lang / "strings.json"

def table(lang):
    p = table_path(lang)
    return json.loads(p.read_text()) if p.exists() else {}

def wordy(s):
    """Worth translating: two or more words and not markup, a URL or an attribute list."""
    return len(s.split()) > 1 and not re.match(r"^(https?:|<!--)", s) and "=" not in s

def md_blocks(text):
    """Paragraphs, headings and list blocks split on blank lines; fenced code stays whole and untranslated."""
    blocks, cur, fence = [], [], False
    for line in text.split("\n"):
        if line.startswith("```"):
            fence = not fence
        if not line.strip() and not fence:
            blocks.append("\n".join(cur)); cur = []
        else:
            cur.append(line)
    return blocks + ["\n".join(cur)]

def keyed(block):
    return wordy(block) and not block.startswith("```")

def md_keys(text):
    keys = []
    for b in md_blocks(text):
        keys += html_keys(b) if b.startswith("<") else [b] if keyed(b) else []
    return keys

def rebase(text, src, dst):
    """Relative links and image paths in text written for src, rewritten to work from dst."""
    def fix(m):
        path, frag = m.group(2).partition("#")[::2]
        if not path or re.match(r"^[a-z]+:|^/", path):
            return m.group(0)
        new = posixpath.relpath(posixpath.normpath(posixpath.join(posixpath.dirname(src), path)), posixpath.dirname(dst))
        new += "/" if path.endswith("/") else ""
        return m.group(1) + new + ("#" + frag if frag else "") + m.group(3)
    return re.sub(r'(\]\(|src=")([^)"\s]+)(\)|")', fix, text)

def md(src, dst, lang):
    t = table(lang)
    out = [html(b, t) if b.startswith("<") else t.get(b) or b if keyed(b) else b for b in md_blocks((ROOT / src).read_text())]
    return HEADER.format(src=src) + rebase("\n\n".join(out), src, dst)

HTML_SEG = re.compile(r"(<(script|style)\b.*?</\2>)|(<[^>]*>)|([^<]+)", re.S)
HTML_ATTR = re.compile(r'\b(content|alt|title|aria-label)="([^"]*)"')

def html_keys(text):
    keys = []
    for m in HTML_SEG.finditer(text):
        if m.group(3):
            keys += [v for _, v in HTML_ATTR.findall(m.group(3)) if wordy(v)]
        elif m.group(4) and wordy(m.group(4).strip()):
            keys.append(m.group(4).strip())
    return keys

def html(text, t):
    """text with every phrase in t replaced, inside text nodes and translatable attributes."""
    def seg(m):
        if m.group(3):
            return HTML_ATTR.sub(lambda a: f'{a.group(1)}="{t.get(a.group(2)) or a.group(2)}"', m.group(3))
        if m.group(4):
            s = m.group(4).strip()
            return m.group(4).replace(s, t.get(s) or s) if s else m.group(4)
        return m.group(0)
    return HTML_SEG.sub(seg, text)

def landing(lang):
    """The landing in lang: every phrase from the table, plus lang attribute, canonical URL and switcher state."""
    out = html((ROOT / LANDING).read_text(), table(lang))
    out = out.replace('<html lang="en">', f'<html lang="{LANGS[lang]}">')
    out = re.sub(rf'(rel="canonical" href="|og:url" content="){SITE}"', rf'\g<1>{SITE}{lang}/"', out)
    out = out.replace(' aria-current="page">', ">").replace(f'hreflang="{LANGS[lang]}">', f'hreflang="{LANGS[lang]}" aria-current="page">')
    return out

def sources():
    """Every English phrase that needs a translation, in page order."""
    keys = html_keys((ROOT / LANDING).read_text())
    for src in MD:
        keys += md_keys((ROOT / src).read_text())
    return list(dict.fromkeys(keys))

if __name__ == "__main__":
    keys = sources()
    for lang in LANGS:
        old = table(lang)
        new = {k: old.get(k, "") for k in keys}
        table_path(lang).write_text(json.dumps(new, ensure_ascii=False, indent=1) + "\n")
        for src, dst in MD.items():
            dst = dst.format(lang=lang)
            (ROOT / dst).write_text(md(src, dst, lang))
        todo = [k for k, v in new.items() if not v]
        gone = [k for k in old if k not in new]
        print(f"{lang}: {len(todo)} to translate, {len(gone)} dropped" + "".join(f"\n  - {k[:70]!r}" for k in todo))
